};

struct xt_table_info* create_xt_table_info(unsigned int size) {
    struct xt_table_info *table_info;
    size_t total_size = sizeof(*table_info) + size;

    table_info = kzalloc(total_size, GFP_KERNEL);
    if (!table_info) {
        table_info = vzalloc(total_size);
        if (!table_info)
